import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { normalizeOtlp, OtlpError, LIMITS } from './normalize.mjs';
import { createOtlpHook } from './worker-adapter.mjs';
import { validate } from '../src/validate.js';

// Small adversarial wire constructors, NOT the compatibility fixture. fixture.pb
// is generated by the actual pinned Python exporter and tagged middleware.
const cat = (...xs) => Buffer.concat(xs);
function vi(x) { x = BigInt(x); const b = []; do { let v = Number(x & 127n); x >>= 7n; b.push(v | (x ? 128 : 0)); } while (x); return Buffer.from(b); }
const key = (id, wire) => vi(id * 8 + wire);
const msg = (id, bytes) => cat(key(id, 2), vi(bytes.length), bytes);
const txt = (id, value) => msg(id, Buffer.from(value));
const uint = (id, value) => cat(key(id, 0), vi(value));
const fixedBytes = n => { const b = Buffer.alloc(8); b.writeBigUInt64LE(BigInt(n)); return b; };
const fx = (id, n) => cat(key(id, 1), fixedBytes(n));
const dblBytes = n => { const b = Buffer.alloc(8); b.writeDoubleLE(n); return b; };
const dbl = (id, n) => cat(key(id, 1), dblBytes(n));
const attr = (k, value) => cat(txt(1, k), msg(2, typeof value === 'string' ? txt(1, value) : uint(3, value)));
const attrs = (field, { route = '/health', method = 'GET', status = 200, extra } = {}) => cat(...[['http.method', method], ['http.route', route], ['http.status_code', status], ...(extra ? [extra] : [])].map(([k, v]) => msg(field, attr(k, v))));
const TIME = 1792521131286665123n;
const number = ({ gauge = false, value = 1n, time = TIME, start = gauge ? 0n : TIME - 100n, dimensions = {}, extra = Buffer.alloc(0) } = {}) => cat(fx(2, start), fx(3, time), fx(6, value), gauge ? Buffer.alloc(0) : attrs(7, dimensions), extra);
const histogram = ({ counts = [1n, 2n], bounds = [5], count = 3n, sum = 14, extra = Buffer.alloc(0) } = {}) => cat(fx(2, TIME - 100n), fx(3, TIME), fx(4, count), sum === null ? Buffer.alloc(0) : dbl(5, sum), msg(6, cat(...counts.map(fixedBytes))), msg(7, cat(...bounds.map(dblBytes))), attrs(9), extra);
function metric({ name = 'http.server.requests', point = number(), temporality = 2, type = 7, extra = Buffer.alloc(0) } = {}) {
  const gauge = type === 5;
  return cat(txt(1, name), txt(3, gauge ? 'users' : type === 9 ? 'ms' : '1'), msg(type, cat(msg(1, point), gauge ? Buffer.alloc(0) : uint(2, temporality), type === 7 ? uint(3, 1) : Buffer.alloc(0))), extra);
}
function envelope(metrics, resource = Buffer.alloc(0), scope = txt(1, 'open_webui.utils.telemetry.metrics')) {
  return msg(1, cat(msg(1, resource), msg(2, cat(msg(1, scope), ...metrics.map(x => msg(2, x))))));
}
const rejects = (b, code) => assert.rejects(normalizeOtlp(b), e => e instanceof OtlpError && (!code || e.code === code) && !e.message.includes('FAKE'));

test('real tagged Python HTTP export fixture, all five native metrics, no identities', async () => {
  const wire = await readFile(new URL('./fixture.pb', import.meta.url));
  const { points, duplicates } = await normalizeOtlp(wire);
  const proof = JSON.parse(await readFile(new URL('./fixture-proof.json', import.meta.url)));
  assert.equal(createHash('sha256').update(wire).digest('hex'), proof.safe_payload_sha256);
  assert.equal(duplicates, 0); assert.equal(points.length, 11);
  assert.equal(new Set(points.map(p => p.metric)).size, 5);
  assert.ok(!wire.includes(Buffer.from('FAKE_')));
  assert.ok(!JSON.stringify(points).includes('authorization'));
  for (const p of points) {
    assert.equal(BigInt(p.timeUnixNano).toString(), p.timeUnixNano);
    if (p.kind === 'histogram') {
      assert.equal(p.bucketCounts.reduce((x, y) => x + BigInt(y), 0n).toString(), p.count);
      assert.equal(p.bucketCounts.length, p.explicitBounds.length + 1);
    }
  }
  const gauges = points.filter(p => p.global);
  assert.deepEqual(gauges.map(p => p.value), ['2', '1', '1']);
  assert.ok(gauges.every(p => p.startTimeUnixNano === '0' && Object.keys(p.dimensions).length === 0));
  assert.deepEqual(JSON.parse(await readFile(new URL('./fixture.normalized.json', import.meta.url))), { points, duplicates });
});

test('unsafe integers and nanoseconds remain exact decimal strings', async () => {
  const value = 9007199254740993n;
  const { points: [p] } = await normalizeOtlp(envelope([metric({ point: number({ value }) })]));
  assert.equal(p.value, value.toString()); assert.equal(p.timeUnixNano, TIME.toString());
});

test('delta and cumulative temporality and resets remain distinct, no implicit rates', async () => {
  for (const temporality of [1, 2]) {
    const a = metric({ temporality, point: number({ start: TIME - 100n }) });
    const b = metric({ temporality, point: number({ start: TIME - 50n }) });
    const { points } = await normalizeOtlp(envelope([a, b]));
    assert.equal(points.length, 2);
    assert.equal(points[0].temporality, temporality === 1 ? 'delta' : 'cumulative');
    assert.notEqual(points[0].startTimeUnixNano, points[1].startTimeUnixNano);
  }
  await rejects(envelope([metric({ temporality: 0 })]), 'unsupported_temporality');
  await rejects(envelope([metric({ point: number({ start: TIME + 1n }) })]), 'invalid_time');
});

test('duplicates within batch suppressed, conflicts rejected, retries produce same normalized points', async () => {
  const a = metric();
  const result = await normalizeOtlp(envelope([a, a]));
  assert.equal(result.points.length, 1); assert.equal(result.duplicates, 1);
  await rejects(envelope([a, metric({ point: number({ value: 2n }) })]), 'conflicting_duplicate');
  assert.deepEqual(await normalizeOtlp(envelope([a])), await normalizeOtlp(envelope([a])));
});

test('global gauges do not gain HTTP or worker dimensions and are not summed', async () => {
  const gauge = metric({ name: 'webui.users.total', type: 5, point: number({ gauge: true, value: 22n }) });
  const { points, duplicates } = await normalizeOtlp(envelope([gauge, gauge]));
  assert.equal(points[0].value, '22'); assert.equal(points[0].global, true); assert.equal(duplicates, 1);
  await rejects(envelope([metric({ name: 'webui.users.total', type: 5, point: number() })]), 'unexpected_dimensions');
});

test('histogram explicit buckets stay disjoint, exact counts and optional min/max', async () => {
  const { points: [p] } = await normalizeOtlp(envelope([metric({ type: 9, name: 'http.server.duration', point: histogram({ counts: [9007199254740993n, 2n], count: 9007199254740995n }) })]));
  assert.deepEqual(p.bucketCounts, ['9007199254740993', '2']);
  assert.deepEqual(p.explicitBounds, [5]); assert.equal(p.count, '9007199254740995');
  const noSum = await normalizeOtlp(envelope([metric({ type: 9, name: 'http.server.duration', point: histogram({ sum: null }) })]));
  assert.ok(!Object.hasOwn(noSum.points[0], 'sum'));
  for (const config of [{ count: 4n }, { bounds: [5, 5], counts: [1n, 1n, 1n] }, { sum: NaN }, { extra: cat(dbl(11, 10), dbl(12, 2)) }]) {
    await rejects(envelope([metric({ type: 9, name: 'http.server.duration', point: histogram(config) })]));
  }
});

test('Worker hook maps native units, exact ns, reset boundary and deterministic receipt', async () => {
  const wire = await readFile(new URL('./fixture.pb', import.meta.url));
  const p = (await normalizeOtlp(wire)).points;
  const now = Number(BigInt(p[0].timeUnixNano) / 1_000_000n) + 2000;
  const hook = createOtlpHook();
  const request = () => new Request('https://example.invalid/v1/otlp/metrics', { method: 'POST', headers: { 'content-type': 'application/x-protobuf' }, body: wire });
  const a = await hook(request(), { source: 'owui', now });
  const b = await hook(request(), { source: 'owui', now: now + 3000 });
  assert.deepEqual(a, b);
  assert.equal(a.points.length, 11);
  assert.equal(a.source, 'owui'); assert.equal(a.schema_version, 1);
  assert.match(a.batch_id, /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
  for (const point of a.points) {
    assert.equal(BigInt(point.time_unix_nano) / 1_000_000n, BigInt(point.observed_at));
    if (point.kind === 'gauge') { assert.equal(point.unit, 'users'); assert.deepEqual(point.attributes, {}); }
    else assert.equal(BigInt(point.start_time_unix_nano) / 1_000_000n, BigInt(point.start_at));
  }
  const validated = validate('metrics', a, {}, now);
  assert.deepEqual(validated.points, a.points);
});

test('Worker hook skips young HTTP series without forging windows; rejects unsafe count conversion', async () => {
  const hook = createOtlpHook();
  const gauge = metric({ name: 'webui.users.total', type: 5, point: number({ gauge: true }) });
  const result = await hook(envelope([metric(), gauge]), { source: 'owui', now: Number(TIME / 1_000_000n) });
  assert.equal(result.points.length, 1); assert.equal(result.points[0].kind, 'gauge');
  await assert.rejects(hook(envelope([metric()]), { source: 'owui', now: 1 }), e => e.code === 'no_aggregate_points');
  const tooBig = metric({ name: 'webui.users.total', type: 5, point: number({ gauge: true, value: 9007199254740993n }) });
  await assert.rejects(hook(envelope([tooBig]), { source: 'owui', now: 1 }), e => e.code === 'count_outside_storage_policy');
});

test('fake secrets rejected in unmatched routes, extra dimensions, resources and scope', async () => {
  await rejects(envelope([metric({ point: number({ dimensions: { route: '/FAKE_SECRET' } }) })]), 'unapproved_route');
  await rejects(envelope([metric({ point: number({ dimensions: { method: 'FAKE_SECRET' } }) })]), 'unapproved_method');
  await rejects(envelope([metric({ point: number({ dimensions: { extra: ['user.id', 'FAKE_SECRET'] } }) })]), 'unexpected_dimensions');
  await rejects(envelope([metric()], msg(1, attr('service.name', 'FAKE_SECRET'))), 'unsupported_field');
  await rejects(envelope([metric()], Buffer.alloc(0), txt(1, 'FAKE_SECRET')), 'unsupported_scope');
});

test('unknown metric/fields, exemplars, trace/log structures and flags fail closed', async () => {
  await rejects(envelope([metric({ name: 'secret.metric' })]), 'unsupported_metric');
  await rejects(envelope([metric({ point: number({ extra: msg(5, txt(1, 'FAKE_SECRET')) }) })]), 'unsupported_field');
  await rejects(envelope([metric({ point: number({ extra: uint(8, 1) }) })]), 'unsupported_flags');
  await rejects(envelope([metric({ extra: txt(99, 'FAKE_SECRET') })]), 'unsupported_field');
  await rejects(msg(1, msg(2, msg(2, txt(1, 'FAKE_TRACE_OR_LOG')))));
});

test('Request contract, compression, bounded chunked body and bytes', async () => {
  const wire = envelope([metric()]);
  const req = (headers = {}, body = wire) => new Request('https://example.invalid/v1/metrics', { method: 'POST', headers: { 'content-type': 'application/x-protobuf', ...headers }, body });
  assert.equal((await normalizeOtlp(req())).points.length, 1);
  await assert.rejects(normalizeOtlp(req({ 'content-encoding': 'gzip' })), e => e.status === 415);
  await assert.rejects(normalizeOtlp(req({ 'content-type': 'application/json' })), e => e.status === 415);
  await assert.rejects(normalizeOtlp(req({ 'content-length': String(LIMITS.bytes + 1) })), e => e.status === 413);
  await assert.rejects(normalizeOtlp(req({}, Buffer.alloc(LIMITS.bytes + 1))), e => e.status === 413);
  await rejects(Buffer.alloc(LIMITS.bytes + 1), 'payload_too_large');
});

test('untrusted stream body has a total deadline, not an unlimited slow-drip read', async () => {
  const body = new ReadableStream({ start() {}, cancel() {} });
  const request = new Request('https://example.invalid/v1/otlp/metrics', { method: 'POST', headers: { 'content-type': 'application/x-protobuf' }, body, duplex: 'half' });
  const started = performance.now();
  await assert.rejects(normalizeOtlp(request), e => e.code === 'body_timeout' && e.status === 408);
  assert.ok(performance.now() - started < LIMITS.bodyMs + 1000);
});

test('malformed protobuf, negative counts, truncated integers and bounded metrics/points', async () => {
  for (const b of [Buffer.alloc(0), Buffer.from([10, 255]), Buffer.from([0]), Buffer.from([15]), Buffer.alloc(11, 255)]) await rejects(b);
  await rejects(envelope([metric({ point: number({ value: (1n << 64n) - 1n }) })]), 'invalid_number');
  const wire = envelope([metric()]);
  for (let i = 1; i < wire.length; i++) await rejects(wire.subarray(0, i));
  await rejects(envelope(Array.from({ length: 65 }, () => metric())), 'too_many_metrics');
  const many = cat(txt(1, 'webui.users.total'), txt(3, 'users'), msg(5, cat(...Array.from({ length: 513 }, () => msg(1, number({ gauge: true }))))));
  await rejects(envelope([many]), 'too_many_points');
});
